import SwiftUI
struct Note { let id: Int; let title: String; var isPinned: Bool }
struct NoteScreen: View {
    @State private var note = Note(id: 41, title: "Купить билеты", isPinned: false)
    var body: some View {
        VStack {
            Text(note.title)
            Text("Закреплена: \(note.isPinned)")
            PinEditor(isPinned: $note.isPinned)
        }
    }
}
struct PinEditor: View {
    @Binding var isPinned: Bool
    var body: some View {
        Toggle("Закрепить", isOn: $isPinned)
    }
}

У NoteScreen одно состояние note. PinEditor получает Binding<Bool> к note.isPinned; Toggle записывает через $isPinned. После включения родитель читает true, после выключения — false.

import SwiftUI
struct Note { let id: Int; let title: String; var text: String }
struct NoteScreen: View {
    @State private var note = Note(id: 45, title: "Поездка", text: "Проверить даты")
    var body: some View {
        VStack {
            Text(note.title)
            Text(note.text)
            NoteTextEditor(text: $note.text)
        }
    }
}
struct NoteTextEditor: View {
    @Binding var text: String
    var body: some View {
        TextField("Текст заметки", text: $text)
    }
}

В начале родитель и поле показывают «Проверить даты». После ввода — «Купить билеты», после стирания — пустую строку. Заголовок «Поездка» читается отдельно. Владелец черновика — NoteScreen, редактор получает Binding к text.
